// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: de outubro a dezembro, 1/10 do ano corrente; de janeiro a setembro, 1/10 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08. Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo".
  cicloInicio: { mes: 10, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
const sqlRegistrarAcao = (acao) => {
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra }. Blocos de 500 (VALUES aceita até 1000 linhas).
const sqlCadastros = (linhas) => {
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (Tipo, Id, Nome, Extra) VALUES (origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// Nó "Preparar" (workflow CNN Painel - Solicitações). Lê body.action, valida os campos e monta o SQL.
// A Vercel já conferiu login e perfil (aprovar e recusar: admin); aqui valida de novo, porque o webhook é a fronteira.
// Escritas devolvem uma linha { Resultado, ... } (OK, JA_EXISTE, NAO_ENCONTRADA, STATUS_INVALIDO...).
// Liberar não passa por aqui: é o workflow Ações, com idSolicitacao, que reativa no CNN e fecha a solicitação.
const unwrap = (valor) => {
  if (typeof valor === 'string') {
    try {
      return JSON.parse(valor);
    } catch (erro) {
      return {};
    }
  }

  return valor && typeof valor === 'object' && !Array.isArray(valor) ? valor : {};
};

const item = unwrap($input.first().json);
const body = { ...item, ...unwrap(item.body) };
const action = String(body.action || '').trim();

const erro = (statusCode, mensagem) => [{
  json: { action: 'error', statusCode, response: { error: mensagem } }
}];

const LOGIN = /^[A-Za-z0-9._-]{2,50}$/;
const usuario = String(body.usuario || '').trim();
const motivo = String(body.motivo || '').replace(/\s+/g, ' ').trim();
const inicio = inicioCiclo();
const hoje = hojeSp();

const inteiro = (valor) => {
  const numero = Number(valor);
  return Number.isSafeInteger(numero) && numero > 0 ? numero : null;
};

const cabecalho = `USE INTEGRACAO;
SET NOCOUNT ON;
DECLARE @inicio DATE = ${sqlDate(inicio)};
DECLARE @hoje DATE = ${sqlDate(hoje)};
DECLARE @usuario NVARCHAR(100) = ${sqlS(usuario, 100)};`;

const escrita = (corpo) => `${cabecalho}
SET XACT_ABORT ON;
BEGIN TRANSACTION;
${corpo}
COMMIT TRANSACTION;`;

// Falta vigente do paciente @paciente: a de maior número no ciclo; sem falta no ciclo, a mais recente de antes.
const faltaVigente = `
DECLARE @idAgenda BIGINT, @nome NVARCHAR(200), @dataFalta DATE, @numero INT, @fim DATE;
SELECT TOP (1)
    @idAgenda = f.IdAgenda,
    @nome = f.NomePaciente,
    @dataFalta = f.DataFalta,
    @numero = f.NumeroFalta
FROM dbo.CtlCnnFaltaPaciente f
WHERE f.IdPaciente = @paciente
ORDER BY CASE WHEN f.DataFalta >= @inicio THEN 0 ELSE 1 END, f.NumeroFalta DESC, f.DataFalta DESC, f.IdAgenda DESC;
SET @fim = DATEADD(DAY, ${sqlDiasCase('@numero')}, @dataFalta);

DECLARE @situacao NVARCHAR(20), @referencia BIGINT;
SELECT @situacao = Situacao, @referencia = IdAgendaReferencia
FROM dbo.CtlCnnControlePaciente
WHERE IdPaciente = @paciente;`;

const ok = (query, extra = {}) => [{ json: { action, query, hoje, ...extra } }];

if (action === 'listar') {
  // Todas as abertas e as 300 fechadas mais recentes, com a situação atual do paciente
  // (falta vigente de agora: se mudou, a solicitação está desatualizada).
  return ok(`${cabecalho}

;WITH Ultimas AS (
    SELECT TOP (300) Id
    FROM dbo.CtlCnnSolicitacao
    WHERE Status NOT IN (N'PENDENTE', N'APROVADA')
    ORDER BY AtualizadoEm DESC, Id DESC
)
SELECT
    N'solicitacao' AS _secao,
    s.Id,
    s.IdPaciente,
    s.NomePaciente,
    s.IdAgendaReferencia,
    s.NumeroFalta,
    CONVERT(char(10), s.DataFalta, 23) AS DataFalta,
    CONVERT(char(10), s.DataFimBloqueio, 23) AS DataFimBloqueio,
    s.Motivo,
    s.SolicitadoPor,
    s.SolicitadoEm,
    s.Status,
    s.DecididoPor,
    s.DecididoEm,
    s.MotivoDecisao,
    s.LiberadoPor,
    s.LiberadoEm,
    s.IdAcao,
    v.IdAgenda AS IdAgendaAtual,
    c.Situacao AS SituacaoControle,
    c.IdAgendaReferencia AS ReferenciaControle
FROM dbo.CtlCnnSolicitacao s
OUTER APPLY (
    SELECT TOP (1) f.IdAgenda
    FROM dbo.CtlCnnFaltaPaciente f
    WHERE f.IdPaciente = s.IdPaciente
    ORDER BY CASE WHEN f.DataFalta >= @inicio THEN 0 ELSE 1 END, f.NumeroFalta DESC, f.DataFalta DESC, f.IdAgenda DESC
) v
LEFT JOIN dbo.CtlCnnControlePaciente c
    ON c.IdPaciente = s.IdPaciente
WHERE s.Status IN (N'PENDENTE', N'APROVADA')
   OR s.Id IN (SELECT Id FROM Ultimas)
ORDER BY s.SolicitadoEm DESC, s.Id DESC;

SELECT N'contagem' AS _secao, Status, COUNT(*) AS Quantidade
FROM dbo.CtlCnnSolicitacao
GROUP BY Status;`);
}

if (!LOGIN.test(usuario)) {
  return erro(400, 'Usuário da solicitação ausente.');
}

if (action === 'criar') {
  const paciente = inteiro(body.idPaciente);
  if (!paciente) return erro(400, 'Paciente inválido.');
  if (motivo.length < 5 || motivo.length > 500) return erro(400, 'Informe o motivo (de 5 a 500 caracteres).');

  // Pode pedir: falta vigente com prazo correndo, ainda não liberada no painel para esta falta,
  // e (falta no ciclo) ou (bloqueio de ciclo anterior ainda correndo). Uma solicitação aberta por paciente.
  return ok(escrita(`DECLARE @paciente BIGINT = ${sqlN(paciente)};
${faltaVigente}

DECLARE @aberta BIGINT = (
    SELECT TOP (1) Id FROM dbo.CtlCnnSolicitacao WITH (UPDLOCK, HOLDLOCK)
    WHERE IdPaciente = @paciente AND Status IN (N'PENDENTE', N'APROVADA')
);

IF @idAgenda IS NULL
    SELECT N'SEM_FALTA' AS Resultado
ELSE IF @dataFalta < @inicio AND NOT (@situacao = N'BLOQUEADO' AND @referencia = @idAgenda)
    SELECT N'SEM_FALTA' AS Resultado
ELSE IF @fim < @hoje
    SELECT N'PRAZO_CUMPRIDO' AS Resultado, CONVERT(char(10), @fim, 23) AS DataFimBloqueio
ELSE IF @situacao = N'LIBERADO' AND @referencia = @idAgenda
    SELECT N'JA_LIBERADO' AS Resultado
ELSE IF @aberta IS NOT NULL
    SELECT N'JA_EXISTE' AS Resultado, @aberta AS Id
ELSE
BEGIN
    INSERT INTO dbo.CtlCnnSolicitacao (
        IdPaciente, NomePaciente, IdAgendaReferencia, NumeroFalta, DataFalta, DataFimBloqueio, Motivo, SolicitadoPor
    )
    VALUES (@paciente, @nome, @idAgenda, @numero, @dataFalta, @fim, ${sqlS(motivo, 500)}, @usuario);

    SELECT N'OK' AS Resultado, CONVERT(BIGINT, SCOPE_IDENTITY()) AS Id, @paciente AS IdPaciente, N'PENDENTE' AS Status;
END;`), { idPaciente: paciente });
}

const id = inteiro(body.id);
if (!id) {
  return erro(400, 'Solicitação inválida.');
}

// Lê a solicitação travada para a decisão (duas pessoas clicando ao mesmo tempo: só uma vence).
const travar = `DECLARE @id BIGINT = ${sqlN(id)};
DECLARE @status NVARCHAR(20), @paciente BIGINT, @referenciaSolicitacao BIGINT, @solicitadoPor NVARCHAR(100);
SELECT
    @status = Status,
    @paciente = IdPaciente,
    @referenciaSolicitacao = IdAgendaReferencia,
    @solicitadoPor = SolicitadoPor
FROM dbo.CtlCnnSolicitacao WITH (UPDLOCK, HOLDLOCK)
WHERE Id = @id;`;

if (action === 'aprovar') {
  return ok(escrita(`${travar}
${faltaVigente}

IF @status IS NULL
    SELECT N'NAO_ENCONTRADA' AS Resultado
ELSE IF @status <> N'PENDENTE'
    SELECT N'STATUS_INVALIDO' AS Resultado, @status AS Status
ELSE IF ISNULL(@idAgenda, 0) <> @referenciaSolicitacao
BEGIN
    UPDATE dbo.CtlCnnSolicitacao
    SET Status = N'ENCERRADA',
        MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
        DecididoPor = @usuario, DecididoEm = SYSUTCDATETIME(), AtualizadoEm = SYSUTCDATETIME()
    WHERE Id = @id;
    SELECT N'DESATUALIZADA' AS Resultado, @paciente AS IdPaciente;
END
ELSE IF @fim < @hoje
BEGIN
    UPDATE dbo.CtlCnnSolicitacao
    SET Status = N'ENCERRADA',
        MotivoDecisao = N'Prazo cumprido: a liberação automática cuida deste paciente.',
        DecididoPor = @usuario, DecididoEm = SYSUTCDATETIME(), AtualizadoEm = SYSUTCDATETIME()
    WHERE Id = @id;
    SELECT N'PRAZO_CUMPRIDO' AS Resultado, @paciente AS IdPaciente;
END
ELSE
BEGIN
    UPDATE dbo.CtlCnnSolicitacao
    SET Status = N'APROVADA',
        DecididoPor = @usuario, DecididoEm = SYSUTCDATETIME(), AtualizadoEm = SYSUTCDATETIME()
    WHERE Id = @id;
    SELECT N'OK' AS Resultado, @id AS Id, @paciente AS IdPaciente, N'APROVADA' AS Status;
END;`), { id });
}

if (action === 'recusar') {
  if (motivo.length < 5 || motivo.length > 500) return erro(400, 'Informe o motivo da recusa (de 5 a 500 caracteres).');

  return ok(escrita(`${travar}

IF @status IS NULL
    SELECT N'NAO_ENCONTRADA' AS Resultado
ELSE IF @status NOT IN (N'PENDENTE', N'APROVADA')
    SELECT N'STATUS_INVALIDO' AS Resultado, @status AS Status
ELSE
BEGIN
    UPDATE dbo.CtlCnnSolicitacao
    SET Status = N'RECUSADA',
        MotivoDecisao = ${sqlS(motivo, 500)},
        DecididoPor = @usuario, DecididoEm = SYSUTCDATETIME(), AtualizadoEm = SYSUTCDATETIME()
    WHERE Id = @id;
    SELECT N'OK' AS Resultado, @id AS Id, @paciente AS IdPaciente, N'RECUSADA' AS Status;
END;`), { id });
}

if (action === 'cancelar') {
  if (motivo && motivo.length > 500) return erro(400, 'O motivo passa de 500 caracteres.');
  const admin = body.admin === true;

  return ok(escrita(`${travar}

IF @status IS NULL
    SELECT N'NAO_ENCONTRADA' AS Resultado
ELSE IF @status NOT IN (N'PENDENTE', N'APROVADA')
    SELECT N'STATUS_INVALIDO' AS Resultado, @status AS Status
ELSE IF @solicitadoPor <> @usuario AND ${sqlBit(admin)} = 0
    SELECT N'NAO_PERMITIDO' AS Resultado
ELSE
BEGIN
    UPDATE dbo.CtlCnnSolicitacao
    SET Status = N'CANCELADA',
        MotivoDecisao = ${sqlS(motivo || null, 500)},
        DecididoPor = @usuario, DecididoEm = SYSUTCDATETIME(), AtualizadoEm = SYSUTCDATETIME()
    WHERE Id = @id;
    SELECT N'OK' AS Resultado, @id AS Id, @paciente AS IdPaciente, N'CANCELADA' AS Status;
END;`), { id });
}

return erro(400, 'Ação desconhecida.');

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
const sqlRegistrarAcao = (acao) => {
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra }. Blocos de 500 (VALUES aceita até 1000 linhas).
const sqlCadastros = (linhas) => {
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (Tipo, Id, Nome, Extra) VALUES (origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// Nó "Montar resposta" (workflow CNN Painel - Solicitações). Devolve { statusCode, response }.
const meta = $('Preparar').first().json;

if (meta.action === 'error') {
  return [{ json: { statusCode: meta.statusCode || 400, response: meta.response || { error: 'Requisição inválida.' } } }];
}

const sqlItens = $('Executar').all();
const falha = erroSql(sqlItens);
if (falha) {
  return [{ json: { statusCode: 502, response: { error: `Falha no banco de solicitações: ${String(falha).slice(0, 300)}` } } }];
}

const linhas = linhasSql(sqlItens);
const iso = (valor) => {
  if (!valor) return null;
  const data = valor instanceof Date ? valor : new Date(String(valor).includes('T') || String(valor).endsWith('Z') ? valor : `${String(valor).replace(' ', 'T')}Z`);
  return Number.isNaN(data.getTime()) ? String(valor) : data.toISOString();
};
const dia = (valor) => {
  if (!valor) return null;
  if (valor instanceof Date) return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};
const numero = (valor) => (valor === null || valor === undefined || valor === '' ? null : Number(valor));
const responder = (statusCode, response) => [{ json: { statusCode, response } }];
const ABERTAS = ['PENDENTE', 'APROVADA'];

if (meta.action === 'listar') {
  const itens = linhas
    .filter((linha) => linha._secao === 'solicitacao')
    .map((s) => {
      const aberta = ABERTAS.includes(s.Status);
      const fimPrazo = dia(s.DataFimBloqueio);
      return {
        id: numero(s.Id),
        idPaciente: numero(s.IdPaciente),
        nomePaciente: s.NomePaciente || null,
        idAgenda: numero(s.IdAgendaReferencia),
        numeroFalta: numero(s.NumeroFalta),
        dataFalta: dia(s.DataFalta),
        dataFimBloqueio: fimPrazo,
        motivo: s.Motivo || '',
        solicitadoPor: s.SolicitadoPor || null,
        solicitadoEm: iso(s.SolicitadoEm),
        status: s.Status,
        decididoPor: s.DecididoPor || null,
        decididoEm: iso(s.DecididoEm),
        motivoDecisao: s.MotivoDecisao || null,
        liberadoPor: s.LiberadoPor || null,
        liberadoEm: iso(s.LiberadoEm),
        idAcao: numero(s.IdAcao),
        // Aberta, mas o paciente teve falta nova (aprovar/liberar vão recusar) ou o prazo já acabou.
        desatualizada: aberta && numero(s.IdAgendaAtual) !== numero(s.IdAgendaReferencia),
        prazoCumprido: aberta && Boolean(fimPrazo) && fimPrazo < meta.hoje,
        bloqueado: s.SituacaoControle === 'BLOQUEADO' && numero(s.ReferenciaControle) === numero(s.IdAgendaReferencia),
      };
    });

  const contagem = { PENDENTE: 0, APROVADA: 0, LIBERADA: 0, RECUSADA: 0, CANCELADA: 0, ENCERRADA: 0 };
  for (const linha of linhas.filter((l) => l._secao === 'contagem')) {
    contagem[linha.Status] = numero(linha.Quantidade) || 0;
  }

  return responder(200, { asOf: new Date().toISOString(), hoje: meta.hoje, contagem, itens });
}

// Escritas: criar, aprovar, recusar, cancelar.
const r = linhas.find((linha) => linha.Resultado) || {};
const STATUS_TEXTO = {
  PENDENTE: 'pendente',
  APROVADA: 'aprovada',
  LIBERADA: 'liberada',
  RECUSADA: 'recusada',
  CANCELADA: 'cancelada',
  ENCERRADA: 'encerrada',
};
const RESULTADOS = {
  OK: [200, null],
  SEM_FALTA: [404, 'Paciente sem falta no ciclo para desbloquear.'],
  PRAZO_CUMPRIDO: [409, 'O prazo desta falta já terminou: a liberação automática cuida deste paciente.'],
  JA_LIBERADO: [409, 'O paciente já foi liberado para esta falta.'],
  JA_EXISTE: [409, `Este paciente já tem uma solicitação aberta${r.Id ? ` (#${r.Id})` : ''}: acompanhe na tela Solicitações.`],
  NAO_ENCONTRADA: [404, 'Solicitação não encontrada.'],
  STATUS_INVALIDO: [409, `A solicitação já está ${STATUS_TEXTO[r.Status] || 'fechada'}.`],
  DESATUALIZADA: [409, 'O paciente teve uma falta nova depois da solicitação: ela foi encerrada. Abra uma nova para a falta atual.'],
  NAO_PERMITIDO: [403, 'Só quem abriu a solicitação (ou um administrador) pode cancelá-la.'],
};
const [statusCode, mensagem] = RESULTADOS[r.Resultado] || [502, 'O banco não confirmou a alteração.'];

if (statusCode !== 200) {
  return responder(statusCode, {
    error: mensagem,
    codigo: r.Resultado || 'SEM_RESULTADO',
    ...(r.Id !== undefined && r.Id !== null ? { id: numero(r.Id) } : {}),
  });
}

return responder(meta.action === 'criar' ? 201 : 200, {
  ok: true,
  id: numero(r.Id),
  idPaciente: numero(r.IdPaciente),
  status: r.Status || null,
});
